import React from 'react';
import {StatusBar, View, StyleSheet, Alert} from 'react-native';
import {Provider as PaperProvider, Button, Text, DefaultTheme} from 'react-native-paper';
import {NavigationContainer} from '@react-navigation/native';
import {createNativeStackNavigator} from '@react-navigation/native-stack';
import {useForm, Controller} from 'react-hook-form';
import {QueryClient, QueryClientProvider, useQuery} from '@tanstack/react-query';
import axios from 'axios';
import {create} from 'zustand';
import LoginScreen from './screens/LoginScreen';
import {useAuthStore} from './store/useAuthStore';

type CounterState = {count: number; increment: () => void};

const useCounterStore = create<CounterState>()(set => ({
  count: 0,
  increment: () => set(state => ({count: state.count + 1})),
}));

const queryClient = new QueryClient();
const Stack = createNativeStackNavigator();

const AppIcon = () => <Text>☕</Text>;

const ExampleHome = ({navigation}: any) => {
  const {count, increment} = useCounterStore();
  const logout = useAuthStore(state => state.logout);
  const {control, handleSubmit} = useForm({defaultValues: {nombre: ''}});

  const {data, isLoading} = useQuery({
    queryKey: ['example'],
    queryFn: async () => {
      const resp = await axios.get('https://jsonplaceholder.typicode.com/todos/1');
      return resp.data;
    },
  });

  const handleNotify = async () => {
    if (typeof globalThis !== 'undefined' && 'document' in globalThis) {
      Alert.alert('Notificaciones no disponibles en web');
      return;
    }

    try {
      const PushNotification = require('react-native-push-notification');
      PushNotification.localNotification({
        title: 'Prueba de notificación',
        message: '¡Esta es una notificación local!',
      });
    } catch (err) {
      // Ignorado: solo demo
    }
  };

  return (
    <View style={styles.container}>
      <Text variant="titleLarge">
        <AppIcon /> BeanAuditorApp
      </Text>
      <Button mode="contained" onPress={increment} style={styles.buttonSpacing}>
        Contador Zustand: {count}
      </Button>
      <Button mode="outlined" onPress={handleNotify} style={styles.buttonSpacing}>
        Enviar Notificación
      </Button>
      <Button mode="outlined" onPress={logout} style={styles.buttonSpacing}>
        Cerrar sesión
      </Button>

      <Text variant="titleMedium">Petición API con React Query:</Text>
      {isLoading ? <Text>Loading...</Text> : <Text>{JSON.stringify(data)}</Text>}

      <Controller
        control={control}
        name="nombre"
        render={({field: {value}}) => (
          <>
            <Text variant="bodyLarge" style={styles.sectionSpacing}>
              Formulario (React Hook Form):
            </Text>
            <Button mode="outlined" onPress={handleSubmit(data => Alert.alert(String(data.nombre)))}>
              Enviar: {value}
            </Button>
          </>
        )}
      />
      <Button onPress={() => navigation.navigate('Splash')}>Ir al SplashScreen</Button>
    </View>
  );
};

const SplashFake = () => (
  <View style={styles.container}>
    <Text variant="headlineMedium">SplashScreen de ejemplo</Text>
    <Text>🔒</Text>
    <Text>Implementación completa requiere ajustes nativos.</Text>
  </View>
);

function MainStack() {
  const isLoggedIn = useAuthStore(state => state.isLoggedIn);

  return (
    <Stack.Navigator screenOptions={{headerShown: false}}>
      {isLoggedIn ? (
        <>
          <Stack.Screen name="Home" component={ExampleHome} options={{title: 'Inicio'}} />
          <Stack.Screen name="Splash" component={SplashFake} options={{title: 'Splash'}} />
        </>
      ) : (
        <Stack.Screen name="Login" component={LoginScreen} />
      )}
    </Stack.Navigator>
  );
}

export default function App() {
  return (
    <PaperProvider theme={DefaultTheme}>
      <QueryClientProvider client={queryClient}>
        <NavigationContainer>
          <StatusBar backgroundColor="#6200ee" barStyle="light-content" />
          <MainStack />
        </NavigationContainer>
      </QueryClientProvider>
    </PaperProvider>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 16,
  },
  buttonSpacing: {
    marginVertical: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
});
