import React from 'react';
import {View, StyleSheet, Image} from 'react-native';
import {Text, Button, TextInput, useTheme} from 'react-native-paper';
import {useForm, Controller} from 'react-hook-form';
import {useAuthStore} from '../store/useAuthStore';

const loginImage = {uri: 'https://reactnative.dev/img/tiny_logo.png'}; // Fácilmente configurable

export default function LoginScreen() {
  const theme = useTheme();
  const {username, setUsername, password, setPassword, login} = useAuthStore();
  const {control, handleSubmit, formState: {errors}} = useForm({
    defaultValues: {username, password},
    mode: 'onChange',
  });

  // Formulario envía datos al store, luego llama login
  const onSubmit = () => {
    login();
  };

  return (
    <View style={styles.container}>
      <Text variant="headlineMedium" style={styles.title}>BeanAuditorApp</Text>
      <Image source={loginImage} style={styles.image} resizeMode="contain" />
      <View style={{width: '100%', marginTop: 24}}>
        <Controller
          control={control}
          name="username"
          rules={{required: 'Ingresa tu usuario'}}
          render={({field: {onChange, value, onBlur}}) => (
            <TextInput
              label="Usuario"
              mode="outlined"
              value={value}
              onBlur={onBlur}
              onChangeText={(val) => {
                setUsername(val);
                onChange(val);
              }}
              error={!!errors.username}
              style={styles.input}
              autoCapitalize="none"
            />
          )}
        />
        {errors.username && (
          <Text style={styles.error}>{errors.username.message}</Text>
        )}
        <Controller
          control={control}
          name="password"
          rules={{required: 'Ingresa tu contraseña'}}
          render={({field: {onChange, value, onBlur}}) => (
            <TextInput
              label="Contraseña"
              mode="outlined"
              value={value}
              onBlur={onBlur}
              onChangeText={(val) => {
                setPassword(val);
                onChange(val);
              }}
              secureTextEntry
              error={!!errors.password}
              style={styles.input}
              autoCapitalize="none"
            />
          )}
        />
        {errors.password && (
          <Text style={styles.error}>{errors.password.message}</Text>
        )}
      </View>
      <Button
        mode="contained"
        onPress={handleSubmit(onSubmit)}
        style={styles.loginBtn}
        disabled={!!errors.username || !!errors.password}
      >
        Iniciar sesión
      </Button>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 24,
    backgroundColor: '#fff',
  },
  title: {
    marginBottom: 16,
    fontWeight: 'bold',
  },
  image: {
    width: 120,
    height: 120,
    marginBottom: 16,
  },
  input: {
    marginVertical: 8,
  },
  loginBtn: {
    marginTop: 32,
    width: '100%',
  },
  error: {
    color: '#E53935',
    alignSelf: 'flex-start',
    marginBottom: 4,
    fontSize: 13,
  },
});
